// Verify Lightspeed X-Series (Vend) webhook and parse payload
// LS sends: content-type: application/x-www-form-urlencoded
// Headers: x-vend-webhook-id, x-vend-webhook-source (NOT x-signature)
// Body: { domain_prefix, retailer_id, type, payload: "<JSON string>" }
const headers = $input.first().json.headers || {};
const body = $input.first().json.body;

// Verify this is a real Lightspeed webhook
const vendWebhookId = headers['x-vend-webhook-id'] || headers['X-Vend-Webhook-Id'];
if (!vendWebhookId) {
  throw new Error('Missing x-vend-webhook-id header — not a valid Lightspeed webhook. Headers: ' + Object.keys(headers).join(', '));
}

const parsedBody = typeof body === 'string' ? JSON.parse(body) : body;

// body.payload is a JSON STRING in LS webhooks — must parse it
let sale;
const rawPayload = parsedBody.payload;
if (typeof rawPayload === 'string') {
  sale = JSON.parse(rawPayload);
} else if (typeof rawPayload === 'object' && rawPayload !== null) {
  sale = rawPayload;
} else {
  throw new Error('Invalid webhook: body.payload is ' + typeof rawPayload);
}

const webhookType = parsedBody.type || '';
const domainPrefix = parsedBody.domain_prefix || '';

// Extract customer email early for filtering
const customerEmail = (sale.customer && sale.customer.email) || '';

return [{ json: {
  verified: true,
  webhookType,
  domainPrefix,
  vendWebhookId,
  customerEmail,
  sale
} }];

// Extract sale data + enrich products for tag mapping
const verifyData = $('Verify & Parse Webhook').first().json;
const sale = verifyData.sale;

// Customer data from LS API fetch
const fetchResult = $('Fetch Customer from LS').first().json;
const customerData = fetchResult.data || fetchResult;
const embeddedCustomer = sale.customer || {};
const customerEmail = (customerData.email || embeddedCustomer.email || '').trim().toLowerCase();
const customerFirstName = customerData.first_name || embeddedCustomer.first_name || '';
const customerLastName = customerData.last_name || embeddedCustomer.last_name || '';
const customerPhone = customerData.phone || customerData.mobile || embeddedCustomer.phone || embeddedCustomer.mobile || '';

// Sale details
const saleId = sale.id;
const totals = sale.totals || {};
const saleTotal = parseFloat(totals.total_price || sale.total_price_incl || sale.total_price || 0);
const saleTotalWithTax = parseFloat(totals.total_payment || sale.total_price_incl || 0);
const employeeId = sale.user_id || '';
const employeeName = (sale.user && sale.user.name) || '';
const registerId = sale.register_id || '';
const saleDate = sale.sale_date || sale.created_at || new Date().toISOString();
const invoiceNumber = sale.invoice_number || '';
const saleNote = sale.note || '';

// --- Product enrichment for tag mapping ---
// Build product type lookup: type_id → type_name
const productTypesResp = $('Fetch Product Types').first().json;
const productTypes = (productTypesResp.data || []);
const typeMap = {};
for (const pt of productTypes) {
  typeMap[pt.id] = (pt.name || '').toLowerCase().trim();
}

// Build product lookup: product_id → product_type_id
const allProductsResp = $('Fetch All Products').first().json;
const allProducts = (allProductsResp.data || []);
const productMap = {};
for (const p of allProducts) {
  productMap[p.id] = {
    name: p.name || '',
    product_type_id: p.product_type_id || '',
    typeName: typeMap[p.product_type_id] || ''
  };
}

// Category → tag mapping (from CLAUDE.md)
const categoryTagMap = {
  'tattoo artist': '[client] tattoo',
  'microblader': '[client] tattoo',
  'piercing': '[client] piercing',
  'piercer': '[client] piercing',
  'tooth gem': '[client] piercing'
};

// Also match product names as fallback
const nameTagRules = [
  { pattern: /tattoo/i, tag: '[client] tattoo' },
  { pattern: /microbla/i, tag: '[client] tattoo' },
  { pattern: /pierc/i, tag: '[client] piercing' },
  { pattern: /tooth\s*gem/i, tag: '[client] piercing' }
];

const tags = new Set(['[system] lightspeed-customer']);
const saleProducts = sale.register_sale_products || [];
const enrichedProducts = [];

for (const item of saleProducts) {
  const product = productMap[item.product_id] || {};
  const typeName = product.typeName || '';
  const productName = product.name || '';

  enrichedProducts.push({
    product_id: item.product_id,
    name: productName,
    typeName: typeName,
    price: item.price,
    quantity: item.quantity
  });

  // Match by product type name (primary)
  for (const [key, tag] of Object.entries(categoryTagMap)) {
    if (typeName.includes(key)) {
      tags.add(tag);
    }
  }

  // Match by product name (fallback)
  for (const rule of nameTagRules) {
    if (rule.pattern.test(productName)) {
      tags.add(rule.tag);
    }
  }
}

if (!customerEmail) {
  throw new Error('Sale ' + saleId + ': customer has no email — cannot sync to GHL');
}

return [{
  json: {
    customerEmail,
    customerFirstName,
    customerLastName,
    customerPhone,
    saleId: String(saleId),
    saleTotal,
    saleTotalWithTax,
    saleDate,
    invoiceNumber,
    employeeId: String(employeeId),
    employeeName,
    registerId: String(registerId),
    saleNote,
    tags: Array.from(tags),
    enrichedProducts,
    hasTattoo: tags.has('[client] tattoo'),
    hasPiercing: tags.has('[client] piercing')
  }
}];

// Calculate updated lifetime value and prepare custom field update
const contact = $json.contact || {};
const saleData = $('Extract Sale Data + Tags').first().json;
const matcherData = $('Find/Create Customer').first().json;

// Get existing lifetime value from custom fields
let existingLifetime = 0;
const customFields = contact.customFields || contact.customField || [];
if (Array.isArray(customFields)) {
  const lvField = customFields.find(f =>
    f.key === 'lifetime_value' || f.id === 'lifetime_value'
  );
  if (lvField) {
    existingLifetime = parseFloat(lvField.value || lvField.field_value || 0);
  }
}

const newLifetime = existingLifetime + saleData.saleTotal;
const tags = [...saleData.tags];
if (newLifetime >= 500) tags.push('[system] vip');

return [{
  json: {
    ghl_contact_id: matcherData.ghl_contact_id,
    saleTotal: saleData.saleTotal,
    saleDate: saleData.saleDate,
    saleId: saleData.saleId,
    employeeId: saleData.employeeId,
    employeeName: saleData.employeeName,
    invoiceNumber: saleData.invoiceNumber,
    newLifetime,
    tags
  }
}];
